// Image imports resolve to the bundled URL at build time. Declared explicitly
// rather than through vite/client, because tsconfig pins `types` to node only.
declare module '*.webp' {
  const src: string;
  export default src;
}

declare module '*.png' {
  const src: string;
  export default src;
}

declare module '*.jpg' {
  const src: string;
  export default src;
}

declare module '*.svg' {
  const src: string;
  export default src;
}
